<script setup lang="ts">import { formatDate } from '~/utils/formatters'; definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find, updateStatus } = useEnrollments(); const id = Number(route.params.id); const { data: enrollment } = await useAsyncData(`enrollment-${id}`, () => find(id)); const saving = ref(false); async function changeStatus(status: string) { saving.value = true; try { enrollment.value = await updateStatus(id, status) } finally { saving.value = false } }</script>
<template><div v-if="enrollment" class="page-shell"><PageHeader :title="`${enrollment.student?.first_name} ${enrollment.student?.last_name}`" :description="enrollment.course_offering?.course?.course_title"><template #actions><StatusBadge :status="enrollment.status" /></template></PageHeader><BaseCard><dl class="grid gap-5 sm:grid-cols-3"><div><dt class="text-sm text-[#60728a]">Course</dt><dd class="font-semibold text-[#29445f]">{{ enrollment.course_offering?.course?.course_code }}</dd></div><div><dt class="text-sm text-[#60728a]">Enrolled</dt><dd class="font-semibold text-[#29445f]">{{ formatDate(enrollment.enrollment_date) }}</dd></div><div><dt class="text-sm text-[#60728a]">Section</dt><dd class="font-semibold text-[#29445f]">{{ enrollment.course_offering?.section }}</dd></div></dl><div v-if="enrollment.status === 'enrolled'" class="mt-6 flex flex-wrap gap-3 border-t border-[#e5ecf3] pt-5"><BaseButton variant="secondary" :loading="saving" @click="changeStatus('dropped')">Mark dropped</BaseButton><BaseButton variant="secondary" :loading="saving" @click="changeStatus('withdrawn')">Mark withdrawn</BaseButton><BaseButton :loading="saving" @click="changeStatus('completed')">Mark completed</BaseButton></div></BaseCard></div></template>
